#!/usr/bin/env node
/* EXSA prebuilt bundles — tools/build-bundle.mjs
   Run:  node tools/build-bundle.mjs [--theme <name>]   → regenerates both bundles
         node tools/build-bundle.mjs --check            → exit 1 if either is stale

   Produces (Phase 6):
     dist/exsa.js          — exsa-core.js first, then every behavior in manifest order
                             (each behavior is already DOM-ready guarded at source)
     dist/exsa.bundle.css  — exsa.css + all components + one theme (breeze default).
                             The core carries the @layer order declaration, so the
                             single file keeps the full 9-layer cascade.
   The --check flag verifies the DEFAULT (breeze) bundle — used by the validator. */
import { readFileSync, writeFileSync, readdirSync, existsSync } from 'node:fs';
import { join, dirname, posix } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const manifest = JSON.parse(readFileSync(join(root, 'manifest.json'), 'utf8'));

function themeName() {
  const i = process.argv.indexOf('--theme');
  return (i !== -1 && process.argv[i + 1]) || 'breeze';
}

function banner(file, theme) {
  return `/* EXSA Bundle — ${file}. Generated by tools/build-bundle.mjs (theme: ${theme}). Do not edit by hand.\n   https://exsa.dev · v${manifest.version} · MIT License\n*/\n\n`;
}

/* Relative url() references (e.g. icons/foo.svg) resolve against the bundled file's
   own location. Inside dist/exsa.bundle.css they must be rebased to dist/. */
function rebaseUrl(u, fileDir) {
  const q = u.includes('?') ? '?' + u.split('?')[1] : '';
  const pathPart = u.split('?')[0];
  const abs = posix.normalize(posix.join(fileDir, pathPart));
  return posix.relative('dist', abs).replace(/\\/g, '/') + q;
}
function rewriteUrls(src, file) {
  const fileDir = posix.dirname(file.replace(/\\/g, '/'));
  return src.replace(/url\(\s*['"]?([^'")\s]+)['"]?\s*\)/g, (all, u) => {
    if (/^(data:|https?:|#|\/|var\(|--)/.test(u.trim())) return all;
    return `url(${rebaseUrl(u, fileDir)})`;
  });
}
function readPart(file) {
  return rewriteUrls(readFileSync(join(root, file), 'utf8'), file).trimEnd() + '\n';
}

function buildJs(theme) {
  const parts = [banner('exsa.js', theme)];
  parts.push(readFileSync(join(root, 'dist/js/exsa-core.js'), 'utf8').trimEnd() + '\n');
  const seen = new Set(['exsa-core.js']);
  for (const b of manifest.behaviors || []) {
    const f = b.source;
    if (!f || !existsSync(join(root, f))) continue;
    const name = f.split('/').pop();
    if (seen.has(name)) continue;
    seen.add(name);
    parts.push('\n/* --- ' + (b.id || name) + ' --- */\n');
    parts.push(readFileSync(join(root, f), 'utf8').trimEnd() + '\n');
  }
  return parts.join('');
}

function buildCss(theme) {
  const themeFile = `dist/themes/${theme}.css`;
  if (!existsSync(join(root, themeFile))) throw new Error(`theme not found: ${themeFile}`);
  const parts = [banner('exsa.bundle.css', theme)];
  parts.push(readPart('dist/exsa.css'));
  const seen = new Set();
  const order = [];
  for (const c of manifest.components || []) {
    if (c.css) order.push(c.css.split('?')[0]);
  }
  /* component CSS present on disk but not cataloged in the manifest (e.g. icons.css) */
  for (const name of readdirSync(join(root, 'dist/components')).sort()) {
    if (!name.endsWith('.css')) continue;
    const f = 'dist/components/' + name;
    if (!order.includes(f)) order.push(f);
  }
  for (const f of order) {
    if (seen.has(f)) continue;
    seen.add(f);
    parts.push('\n/* --- ' + f.split('/').pop() + ' --- */\n');
    parts.push(readPart(f));
  }
  parts.push('\n/* --- theme: ' + theme + ' --- */\n');
  parts.push(readPart(themeFile));
  return parts.join('');
}

export function bundleOutputs() {
  const theme = themeName();
  return { js: buildJs(theme), css: buildCss(theme), theme };
}

/* ---------- CLI ---------- */
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const { js, css, theme } = bundleOutputs();
  const kb = (s) => (Buffer.byteLength(s) / 1024).toFixed(1) + ' KB';
  const cur = (f) => (existsSync(join(root, f)) ? readFileSync(join(root, f), 'utf8') : null);
  if (process.argv.includes('--check')) {
    if (cur('dist/exsa.js') !== js || cur('dist/exsa.bundle.css') !== css) {
      console.error('✗ bundles are out of date — run: node tools/build-bundle.mjs');
      process.exit(1);
    }
    console.log(`✓ dist/exsa.js + dist/exsa.bundle.css are up to date (theme ${theme})`);
  } else {
    writeFileSync(join(root, 'dist/exsa.js'), js);
    writeFileSync(join(root, 'dist/exsa.bundle.css'), css);
    console.log(`✓ wrote dist/exsa.js (${kb(js)}) + dist/exsa.bundle.css (${kb(css)}) with theme ${theme}`);
  }
}
